# Let me check the conv3 biases for the channels with highest fc.weight per class
print("Top fc.weight channels per class and their conv3 biases:")
for i in range(10):
    # Get top 3 channels for this class
    top_channels = np.argsort(fc_w[i])[-3:]
    print(f"\nClass {i} ({CLASSES[i]}):")
    for c in reversed(top_channels):
        print(f"  Channel {c}: fc_w={fc_w[i,c]:.4f}, conv3_bias={conv3_b[c]:.4f}, conv3_norm={conv3_norms[c]:.4f}")

# Also check: for each class, sum of fc.weight * conv3_bias for channels where both are positive
print("\n\nSum of (fc_weight * conv3_bias) for positive pairs per class:")
for i in range(10):
    total = 0
    count = 0
    for c in range(64):
        if fc_w[i,c] > 0 and conv3_b[c] > 0:
            total += fc_w[i,c] * conv3_b[c]
            count += 1
    print(f"  Class {i}: sum={total:.4f}, count={count}")

# And sum of fc_weight for channels with high bias (>0.4)
print("\nSum of fc_weight for channels with bias > 0.4 per class:")
for i in range(10):
    total = 0
    channels = []
    for c in range(64):
        if conv3_b[c] > 0.4:
            total += fc_w[i,c]
            channels.append((c, fc_w[i,c]))
    print(f"  Class {i}: sum={total:.4f}")
    for c, w in sorted(channels, key=lambda x: -x[1])[:5]:
        print(f"    Channel {c}: fc_w={w:.4f}, bias={conv3_b[c]:.4f}")

# Let me do a final review of the changes before submitting
print("=== SUMMARY OF CHANGES ===")

print("\n1. conv3.bias clipping (threshold=0.4):")
original_bias = W['conv3.bias'].detach().cpu().numpy()
modified_bias = W_modified['conv3.bias'].detach().cpu().numpy()
for c in range(64):
    if original_bias[c] != modified_bias[c]:
        print(f"  Channel {c}: {original_bias[c]:.4f} -> {modified_bias[c]:.4f}")

print("\n2. fc.weight for ship class (class 8) reductions:")
original_ship = W['fc.weight'][8].detach().cpu().numpy()
modified_ship = W_modified['fc.weight'][8].detach().cpu().numpy()
for c in range(64):
    if original_ship[c] != modified_ship[c]:
        print(f"  Channel {c}: {original_ship[c]:.4f} -> {modified_ship[c]:.4f}")

print("\n3. Overall statistics:")
print(f"  conv3.bias max: {original_bias.max():.4f} -> {modified_bias.max():.4f}")
print(f"  conv3.bias mean: {original_bias.mean():.4f} -> {modified_bias.mean():.4f}")
print(f"  Ship fc.weight mean: {original_ship.mean():.4f} -> {modified_ship.mean():.4f}")
print(f"  Ship fc.weight max: {original_ship.max():.4f} -> {modified_ship.max():.4f}")

# Check that we didn't break anything else
print("\n4. Other weights unchanged:")
for k in W.keys():
